"""Generate named bindings from complete signatures used by native consumers."""

import argparse
import json
import re
from pathlib import Path


ROOT = Path(__file__).resolve().parent


def generate(catalog):
    if catalog["schema"] != 1:
        raise ValueError("Unsupported native function schema")
    entries = catalog["functions"]
    names = [entry["field"] for entry in entries + catalog.get("vtable_functions", [])]
    if len(names) != len(set(names)):
        raise ValueError("Duplicate native function field")
    lines = [
        "// Generated by game/functions/generate.py. Do not edit by hand.",
        "#pragma once",
        '#include "game/layouts/native_objects.h"',
        "",
        "namespace native_game {",
        "",
        "class NativeFunctions {",
        "public:",
        "    NativeFunctions(const std::byte* executable_base, const Profile& addresses)",
        "        : image_(executable_base), addresses_(addresses) {}",
        "",
    ]
    for entry in entries + catalog.get("vtable_functions", []):
        field = entry["field"]
        result = entry["return"]
        convention = entry["convention"]
        if not re.fullmatch(r"[a-z][a-z_]*", field):
            raise ValueError(f"Invalid field: {field}")
        if convention not in ("__stdcall", "__thiscall") or not entry["evidence"]:
            raise ValueError(f"Incomplete signature evidence: {field}")
        alias = "".join(word.title() for word in field.split("_"))
        types = ", ".join(kind for kind, _ in entry["params"])
        params = ", ".join(f"{kind} arg_{name}" for kind, name in entry["params"])
        args = ", ".join(f"arg_{name}" for _, name in entry["params"])
        vtable = "slot" in entry
        target_params = "void* arg_object" if vtable else ""
        binding = (f"bind_vtable<{alias}>(arg_object, {entry['slot']})" if vtable
                   else f"bind<{alias}>(addresses_.{field})")
        target_args = "arg_object" if vtable else ""
        lines += [
            f"    using {alias} = {result}({convention}*)({types});",
            f"    {alias} {field}_target({target_params}) const {{",
            f"        return {binding};",
            "    }",
            f"    {result} {field}({params}) const {{",
            f"        return {field}_target({target_args})({args});",
            "    }",
            "",
        ]
    lines += [
        "private:",
        "    template <class Function> Function bind(std::uint32_t rva) const {",
        "        return image_ ? reinterpret_cast<Function>(image_ + rva) : nullptr;",
        "    }",
        "",
        "    template <class Function> Function bind_vtable(void* object, std::size_t slot) const {",
        "        const auto methods = *static_cast<void***>(object);",
        "        return reinterpret_cast<Function>(methods[slot]);",
        "    }",
        "",
        "    const std::byte* image_;",
        "    const Profile& addresses_;",
        "};",
        "}",
        "",
    ]
    return "\n".join(lines)


def generate_runtime(catalog):
    lines = [
        "// Generated by game/functions/generate.py. Do not edit by hand.",
        "#pragma once",
        '#include "generated.h"',
        '#include "game/access/memory.h"',
        '#include "game/layouts/script.h"',
        '#include "game/profiles/variables.h"',
        "",
        "namespace native_game {",
        "class NativeRuntime : public NativeFunctions {",
        "public:",
        "    NativeRuntime(const std::byte* executable_base, const Profile& addresses)",
        "        : NativeFunctions(executable_base, addresses), image_(executable_base), addresses_(addresses) {}",
        "",
    ]
    for field, kind in catalog["globals"]:
        lines += [
            f"    MemoryRef<{kind}> {field}() const {{",
            f"        return global<{kind}>(addresses_.{field});",
            "    }",
            "",
        ]
    for method, field in catalog["identities"]:
        lines += [
            f"    const void* {method}() const {{",
            f"        return location(addresses_.{field});",
            "    }",
            "",
        ]
    lines += [
        "    MemoryRef<std::uint32_t> registered_variable(const VariableSlot& slot) const {",
        "        const auto rva = slot.rva(addresses_);",
        "        return MemoryRef<std::uint32_t>(rva ? location(rva) : nullptr, &addresses_);",
        "    }",
        "",
        "private:",
        "    const void* location(std::uint32_t rva) const {",
        "        return image_ ? image_ + rva : nullptr;",
        "    }",
        "    template <class T> MemoryRef<T> global(std::uint32_t rva) const {",
        "        return MemoryRef<T>(location(rva), &addresses_);",
        "    }",
        "    const std::byte* image_;",
        "    const Profile& addresses_;",
        "};",
        "}",
        "",
    ]
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    catalog = json.loads((ROOT / "catalog.json").read_text(encoding="utf-8"))
    known = json.loads((ROOT.parent / "profiles/functions.json").read_text(encoding="utf-8"))
    covered = [entry["field"] for entry in catalog["functions"] + catalog["unbound"]]
    if len(covered) != len(set(covered)) or set(covered) != {row["field"] for row in known["functions"]}:
        raise ValueError("Function catalog must account for every profile function exactly once")
    for filename, generated in (("generated.h", generate(catalog)),
                                ("runtime.h", generate_runtime(catalog))):
        output = ROOT / filename
        if args.check:
            normalize = lambda text: re.sub(r"\s+", "", text)
            if not output.exists() or normalize(output.read_text(encoding="utf-8")) != normalize(generated):
                raise SystemExit(f"Native bindings {filename} are stale. Run game/functions/generate.py")
        else:
            output.write_text(generated, encoding="utf-8", newline="\n")


if __name__ == "__main__":
    main()
